(function () {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;


  /* ================= SOUND ENGINE ================= */
  const music = new Audio(); music.loop = true; music.preload = "none"; music.volume = .75;
  let soundOwner = null;
  const eqHTML = '<span class="eqi"><i></i><i></i><i></i></span>';
  function syncButtons() {
    document.querySelectorAll("[data-snd]").forEach(b => {
      const on = soundOwner === b.dataset.snd && !music.paused;
      b.classList.toggle("on", on);
      const lbl = b.querySelector(".lbl"); if (lbl) lbl.textContent = on ? (b.dataset.on || "Sound on") : (b.dataset.off || "Tap for sound");
    });
    const hb = document.getElementById("soundBtn");
    if (hb) { const on = soundOwner === "hero" && !music.paused; hb.classList.toggle("on", on); hb.setAttribute("aria-pressed", on); const l = document.getElementById("soundLabel"); if (l) l.textContent = on ? "Sound on" : "Sound off"; }
  }
  function playTrack(track, owner) {
    const src = TRACKS[track] || TRACKS.groove;
    if (!music.src.endsWith(src)) { music.src = src; music.currentTime = 0; }
    soundOwner = owner;
    music.play().then(syncButtons).catch(syncButtons);
    syncButtons();
  }
  function stopTrack() { music.pause(); soundOwner = null; syncButtons(); }
  function toggleTrack(track, owner) { (soundOwner === owner && !music.paused) ? stopTrack() : playTrack(track, owner); }
  window.__jdc = { playTrack, stopTrack, music };
  document.addEventListener("click", e => {
    const b = e.target.closest("[data-snd]"); if (!b) return;
    e.preventDefault(); e.stopImmediatePropagation();
    toggleTrack(b.dataset.track, b.dataset.snd);
    const v = b.closest(".vcard, .svc-mock")?.querySelector("video"); if (v) v.play().catch(() => {});
  });
  music.addEventListener("pause", syncButtons); music.addEventListener("play", syncButtons);

  /* links */
  const waURL = "https://wa.me/" + SITE.whatsapp + "?text=" + encodeURIComponent("Hi Jennie, I'd like to work with you on my music.");
  $$(".wa-link").forEach(a => { a.href = waURL; a.target = "_blank"; a.rel = "noopener"; });
  $$(".mail-link").forEach(a => a.href = "mailto:" + SITE.email + "?subject=" + encodeURIComponent("Booking enquiry — Jennie Dance Crew"));
  $$("[data-social]").forEach(a => { a.href = SITE[a.dataset.social]; a.target = "_blank"; a.rel = "noopener"; });
  $$(".yr").forEach(el => el.textContent = new Date().getFullYear());

  /* active nav */
  const page = document.body.dataset.page;
  $$("[data-link]").forEach(a => a.classList.toggle("active", a.dataset.link === page));

  /* mobile menu */
  const burger = $("#burger");
  if (burger) burger.addEventListener("click", () => {
    const open = document.body.classList.toggle("menu-open");
    burger.setAttribute("aria-expanded", open);
  });
  $$("#links a").forEach(a => a.addEventListener("click", () => document.body.classList.remove("menu-open")));

  /* header on scroll */
  const header = $("#top");
  const onScroll = () => header.classList.toggle("scrolled", scrollY > 30);
  window.addEventListener("scroll", onScroll, { passive: true }); onScroll();

  /* cursor glow */
  const glow = $("#glow");
  if (glow) {
    if (matchMedia("(pointer:fine)").matches) window.addEventListener("pointermove", e => glow.style.transform = `translate(${e.clientX - 310}px, ${e.clientY - 310}px)`);
    else glow.style.transform = "translate(-20%, -10%)";
  }

  /* hero video + sound toggle */
  const heroVid = $("#heroVideo");
  if (heroVid) {
    heroVid.innerHTML = `<source src="${HERO_VIDEO}" type="video/mp4"><source src="${HERO_VIDEO.replace("-720.mp4", "-360.mp4")}" type="video/mp4">`; heroVid.load();
    heroVid.addEventListener("canplay", () => heroVid.classList.add("on"), { once: true });
    if (!reduce) heroVid.play().catch(() => {});
    heroVid.muted = true;
    $("#soundBtn").addEventListener("click", () => toggleTrack("groove", "hero"));
  }

  /* work cards — videos play right on the page */
  const eyeIcon = '<svg viewBox="0 0 24 24"><path d="M12 5C6 5 2 12 2 12s4 7 10 7 10-7 10-7-4-7-10-7zm0 11a4 4 0 1 1 0-8 4 4 0 0 0 0-8z"/></svg>';
  function card(w) {
    const i = WORK.indexOf(w);
    if (w.type === "youtube") return `<div class="vcard" data-cat="${w.group || w.cat}">
      <div class="media"><iframe loading="lazy" src="https://www.youtube-nocookie.com/embed/${w.src}?rel=0&modestbranding=1&playsinline=1" title="${w.title}" allow="accelerometer; autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe></div>
      <div class="cap"><div><small>${w.cat}</small><b>${w.title}</b></div><button class="full" data-open="${i}">▶ Play</button></div></div>`;
    if (w.type === "file") return `<div class="vcard" data-cat="${w.group || w.cat}">
      <div class="media" data-open="${i}" role="button" tabindex="0" aria-label="Play ${w.title}"><span class="live">Playing</span><span class="bigplay"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></span><button class="snd" data-snd="card${i}" data-track="${w.track || "groove"}">${eqHTML}<span class="lbl">Tap for sound</span></button><video class="lazyplay" muted loop playsinline preload="none" ${w.poster ? `poster="${w.poster}"` : ""}><source src="${w.src}" type="video/mp4">${w.src.includes("-720.mp4") ? `<source src="${w.src.replace("-720.mp4", "-360.mp4")}" type="video/mp4">` : ""}</video></div>
      <div class="cap"><div><small>${w.cat}</small><b>${w.title}</b></div><button class="full" data-open="${i}">▶ Play</button></div></div>`;
    if (w.type === "mock") return `<div class="vcard" data-cat="${w.group}">
      <div class="media mockmedia" data-open="${i}" role="button" tabindex="0" aria-label="Open ${w.title}"><div class="scalebox"><div class="svc-mock mk-${w.kind} ${(SAMPLES[w.cfg] || {}).theme || ""}" data-mock="${w.kind}" data-cfg="${w.cfg}"></div></div>${w.kind === "lyric" ? `<span class="bigplay"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></span>` : `<span class="bigview"><svg viewBox="0 0 24 24"><path d="M12 5C6 5 2 12 2 12s4 7 10 7 10-7 10-7-4-7-10-7zm0 11a4 4 0 1 1 0-8 4 4 0 0 1 0 8z"/></svg>View design</span>`}</div>
      <div class="cap"><div><small>${w.cat}</small><b>${w.title}</b></div><button class="full" data-open="${i}">${w.kind === "lyric" ? "▶ Play" : "View design"}</button></div></div>`;
    return `<button class="work" data-cat="${w.group || w.cat}" data-open="${i}" aria-label="Open ${w.title}">
      <img loading="lazy" src="${w.src}" alt="${w.title}"><span class="playbtn">${eyeIcon}</span>
      <span class="meta"><small>${w.cat}</small><b>${w.title}</b></span></button>`;
  }
  $$("[data-grid]").forEach(g => {
    let list = WORK, spec = g.dataset.grid || "";
    if (spec.startsWith("videos")) { list = WORK.filter(w => w.type === "file" || w.type === "youtube"); spec = spec.split(":")[1] || ""; }
    g.innerHTML = list.slice(0, +spec || list.length).map(card).join("");
  });

  /* play card videos only while on screen */
  const vio = new IntersectionObserver(es => es.forEach(e => {
    const v = e.target;
    if (e.isIntersecting) { if (v.preload === "none") { v.preload = "auto"; v.load(); } v.play().catch(() => {}); }
    else v.pause();
  }), { threshold: .25 });
  $$("video.lazyplay").forEach(v => vio.observe(v));

  /* filters */
  const filters = $("#filters");
  if (filters) {
    const cats = ["All work", ...new Set(WORK.map(w => w.group || w.cat))];
    filters.innerHTML = cats.map((c, i) => `<button class="${i ? "" : "active"}" data-filter="${i ? c : "all"}">${c}</button>`).join("");
    filters.addEventListener("click", e => {
      const b = e.target.closest("button"); if (!b) return;
      $$("button", filters).forEach(x => x.classList.toggle("active", x === b));
      $$("#fullGrid .work, #fullGrid .vcard").forEach(w => w.classList.toggle("hide", b.dataset.filter !== "all" && w.dataset.cat !== b.dataset.filter));
    });
  }

  /* modal */
  const modal = $("#modal"), inner = $("#modalInner");
  /* ---------- Lightbox player: click any piece, it plays right here ---------- */
  let lbList = [], lbPos = 0;
  if (modal) {
    modal.insertAdjacentHTML("beforeend", `
      <button class="lb-nav prev" aria-label="Previous">‹</button>
      <button class="lb-nav next" aria-label="Next">›</button>
      <div class="lb-info"><div><small class="lb-cat"></small><b class="lb-title"></b></div><span class="lb-count"></span>
        <button class="lb-snd" data-snd="modal" data-track="groove" data-off="Sound off" data-on="Sound on"><span class="eqi"><i></i><i></i><i></i></span><span class="lbl">Sound off</span></button></div>
      <div class="lb-strip"></div>`);
  }
  function visibleList() {
    const cards = $$("[data-grid] .vcard:not(.hide), [data-grid] .work:not(.hide), .gallery .work");
    const ids = [...new Set(cards.map(c => +(c.querySelector("[data-open]")?.dataset.open ?? c.dataset.open)).filter(n => !isNaN(n)))];
    return ids.length ? ids : WORK.map((_, i) => i);
  }
  function render(i) {
    const w = WORK[i]; if (!w) return;
    if (soundOwner && soundOwner.startsWith("mk") && inner.contains(document.querySelector(`[data-snd="${soundOwner}"]`))) stopTrack();
    inner.className = "modal-inner" + (w.type === "photo" ? " photo" : "");
    inner.style.animation = "none"; inner.offsetHeight; inner.style.animation = "";
    if (w.type === "youtube") { stopTrack(); inner.innerHTML = `<iframe src="https://www.youtube-nocookie.com/embed/${w.src}?autoplay=1&rel=0&modestbranding=1" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen title="${w.title}"></iframe>`; }
    else if (w.type === "file") {
      inner.innerHTML = `<video controls muted autoplay loop playsinline ${w.poster ? `poster="${w.poster}"` : ""}><source src="${w.src}" type="video/mp4">${w.src.includes("-720.mp4") ? `<source src="${w.src.replace("-720.mp4", "-360.mp4")}" type="video/mp4">` : ""}</video>`;
      inner.querySelector("video").play().catch(() => {});
      const sb = $(".lb-snd", modal); sb.dataset.track = w.track || "groove"; sb.style.display = "";
      if (soundOwner === "modal" || lbWantsSound) playTrack(w.track || "groove", "modal");
    } else if (w.type === "mock") {
      if (soundOwner === "modal" || w.kind !== "lyric") stopTrack();
      inner.className = "modal-inner mockbox";
      inner.innerHTML = `<div class="scalebox"><div class="svc-mock mk-${w.kind} ${(SAMPLES[w.cfg] || {}).theme || ""}${w.kind === "web" ? " is-full" : ""}" data-mock="${w.kind}" data-cfg="${w.cfg}" ${w.kind === "web" ? 'data-full="1"' : ""}></div></div>`;
      fillMocks(inner);
      const vp = inner.querySelector(".is-full .viewport");
      if (vp) vp.addEventListener("scroll", () => vp.parentElement.classList.toggle("scrolled", vp.scrollTop > 20), { passive: true }); sro.observe(inner.querySelector(".scalebox"));
      $(".lb-snd", modal).style.display = "none";
      if (w.kind === "lyric" && lbWantsSound) { const b = $(".snd", inner); if (b) playTrack(b.dataset.track, b.dataset.snd); }
    } else { inner.innerHTML = `<img src="${w.src}" alt="${w.title}">`; $(".lb-snd", modal).style.display = "none"; }
    $(".lb-cat", modal).textContent = w.cat; $(".lb-title", modal).textContent = w.title;
    $(".lb-count", modal).textContent = (lbPos + 1) + " / " + lbList.length;
    $$(".lb-strip button", modal).forEach((t, k) => t.classList.toggle("active", k === lbPos));
    $(".lb-strip button.active", modal)?.scrollIntoView({ block: "nearest", inline: "center", behavior: "smooth" });
  }
  let lbWantsSound = true;
  function openItem(i) {
    if (!modal) return;
    lbList = visibleList(); if (!lbList.includes(i)) lbList = WORK.map((_, k) => k);
    lbPos = lbList.indexOf(i);
    $(".lb-strip", modal).innerHTML = lbList.map(k => { const w = WORK[k]; const th = w.poster || (w.type === "photo" ? w.src : (w.type === "youtube" ? `https://i.ytimg.com/vi/${w.src}/mqdefault.jpg` : "")); return `<button aria-label="${w.title}" data-lb="${k}" class="${w.type === "mock" ? "mk-th th-" + w.kind : ""}">${th ? `<img src="${th}" alt="">` : `<span><small>${w.cat}</small>${w.title}</span>`}</button>`; }).join("");
    lbWantsSound = true;
    modal.classList.add("open"); document.body.style.overflow = "hidden";
    if (heroVid) heroVid.pause();
    render(i);
  }
  function step(d) { if (!lbList.length) return; lbPos = (lbPos + d + lbList.length) % lbList.length; render(lbList[lbPos]); }
  function closeItem() {
    if (!modal || !modal.classList.contains("open")) return;
    modal.classList.remove("open"); inner.innerHTML = ""; document.body.style.overflow = "";
    if (soundOwner === "modal" || (soundOwner && soundOwner.startsWith("mk") && !document.querySelector(`[data-snd="${soundOwner}"]`))) stopTrack();
    if (heroVid && !reduce) heroVid.play().catch(() => {});
  }
  if (modal) {
    $(".lb-nav.prev", modal).addEventListener("click", e => { e.stopPropagation(); step(-1); });
    $(".lb-nav.next", modal).addEventListener("click", e => { e.stopPropagation(); step(1); });
    $(".lb-strip", modal).addEventListener("click", e => { const t = e.target.closest("[data-lb]"); if (!t) return; e.stopPropagation(); lbPos = lbList.indexOf(+t.dataset.lb); render(+t.dataset.lb); });
    $(".lb-snd", modal).addEventListener("click", () => setTimeout(() => { lbWantsSound = soundOwner === "modal"; }, 0));
    let sx = null;
    modal.addEventListener("touchstart", e => sx = e.touches[0].clientX, { passive: true });
    modal.addEventListener("touchend", e => { if (sx === null) return; const dx = e.changedTouches[0].clientX - sx; if (Math.abs(dx) > 50) step(dx < 0 ? 1 : -1); sx = null; });
  }
  document.addEventListener("keydown", e => {
    if (!modal?.classList.contains("open")) return;
    if (e.key === "ArrowRight") step(1); if (e.key === "ArrowLeft") step(-1);
  });
  document.addEventListener("keydown", e => { if ((e.key === "Enter" || e.key === " ") && e.target.matches?.(".media[data-open]")) { e.preventDefault(); openItem(+e.target.dataset.open); } });
  document.addEventListener("click", e => { const t = e.target.closest("[data-open]"); if (t) { e.preventDefault(); openItem(+t.dataset.open); } });
  if (modal) {
    $("#modalClose").addEventListener("click", closeItem);
    modal.addEventListener("click", e => { if (e.target === modal) closeItem(); });
  }
  document.addEventListener("keydown", e => { if (e.key === "Escape") { closeItem(); document.body.classList.remove("menu-open"); } });

  /* reveal on scroll */
  const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } }), { threshold: .12 });
  $$(".rv").forEach(el => io.observe(el));

  /* counters */
  const co = new IntersectionObserver(es => es.forEach(e => {
    if (!e.isIntersecting) return; co.unobserve(e.target);
    const el = e.target, end = +el.dataset.count, suf = el.dataset.suffix || "+", t0 = performance.now();
    (function tick(t) { const p = Math.min((t - t0) / 1600, 1); el.textContent = Math.round(end * (1 - Math.pow(1 - p, 3))) + suf; if (p < 1) requestAnimationFrame(tick); })(t0);
  }), { threshold: .5 });
  $$("[data-count]").forEach(el => co.observe(el));

  /* lyric demo */
  const line = $("#lyricLine"), wave = $("#lyricWave");
  if (line) {
    const LYRICS = [["Turn", "the", "lights", "down", "low"], ["let", "the", "*bassline", "speak"], ["every", "word", "you", "*feel"], ["moving", "on", "the", "*beat"]];
    for (let i = 0; i < 14; i++) { const b = document.createElement("i"); b.style.animationDelay = (i * .08) + "s"; wave.appendChild(b); }
    let li = 0;
    (function show() {
      const words = LYRICS[li++ % LYRICS.length];
      line.innerHTML = words.map(w => `<span class="w${w[0] === "*" ? " hot" : ""}">${w.replace("*", "")}</span>`).join("");
      [...line.children].forEach((s, i) => setTimeout(() => s.classList.add("on"), 260 * i + 80));
      setTimeout(show, 260 * words.length + 1500);
    })();
  }

  /* preselect service from ?service= */
  const sel = $("#f-service"), qs = new URLSearchParams(location.search).get("service");
  if (sel && qs) [...sel.options].forEach(o => { if (o.text === qs) sel.value = o.text; });

  /* contact form → email */
  const form = $("#contactForm");
  if (form) form.addEventListener("submit", e => {
    e.preventDefault();
    const g = id => $("#" + id).value.trim(), note = $("#formNote");
    if (!g("f-name") || !/^\S+@\S+\.\S+$/.test(g("f-email"))) {
      note.textContent = "Add your name and a valid email address so Jennie can reply."; note.style.color = "#8C1D40"; return;
    }
    const body = `Name: ${g("f-name")}\nEmail: ${g("f-email")}\nArtist/brand: ${g("f-artist")}\nRelease date: ${g("f-date")}\nProject type: ${g("f-service")}\nBudget: ${g("f-budget")}\n\n${g("f-msg")}`;
    location.href = `mailto:${SITE.email}?subject=${encodeURIComponent("Project enquiry — " + g("f-service"))}&body=${encodeURIComponent(body)}`;
    note.textContent = "Your email app is opening with the details filled in. Press send to finish."; note.style.color = "";
  });


  /* ================= PREMIUM SERVICE MOCKUPS ================= */
  const vid = (id, cls = "") => `<video class="${cls}" muted loop playsinline autoplay preload="metadata" poster="${MKP(id)}"><source src="${MK(id)}" type="video/mp4"><source src="${MK(id).replace("-720.mp4", "-360.mp4")}" type="video/mp4"></video>`;
  const sndBtn = (id, track, off = "Tap for sound") => `<button class="snd" data-snd="${id}" data-track="${track}" data-off="${off}">${eqHTML}<span class="lbl">${off}</span></button>`;
  let mkCount = 0;
  const MOCK = {
    dance: () => `
      <div class="phone back"><span class="notch"></span>${vid(43209)}</div>
      <div class="phone front"><span class="notch"></span>${vid(43219)}
        <div class="ph-top"><span>Following</span><b>For You</b></div>
        <div class="ph-side"><span class="av"><img src="${OWNER}" alt=""></span><span class="like">♥<small data-likes>128K</small></span><span>💬<small>2.4K</small></span><span>↗<small>9.1K</small></span><span class="disc"></span></div>
        <div class="ph-cap"><b>@jenniedancecrew</b><div>New routine for the single 🔥 #dancechallenge</div><div class="ticker"><span>♫ Midnight Frequency · Original sound · Jennie Dance Crew ♫ Midnight Frequency · Original sound</span></div></div>
        <div class="hearts"></div>
      </div>
      <div class="chip c1">Views <b data-num="1240000" data-fmt="k">0</b></div>
      <div class="chip c2"># <b>1</b> trending sound</div>
      ${sndBtn("mk" + (++mkCount), "groove")}`,
    lyric: (c = SAMPLES.ly1) => `
      <div class="ly-bg"></div>
      <div class="ly-title">Now playing<b>${c.title}</b><span class="ly-artist">${c.artist}</span></div>
      <div class="ly-cover"><span class="vin"></span><img src="${OWNER}" alt=""></div>
      <div class="ly-words" data-lines="${JSON.stringify(c.lines).replace(/"/g, "&quot;")}" data-bpm="${c.bpm}" data-track="${c.track}"></div>
      <div class="ly-wave">${Array.from({ length: 28 }, (_, i) => `<i style="animation-delay:${(i * 0.06).toFixed(2)}s"></i>`).join("")}</div>
      <div class="ly-bar"><span class="t">0:00</span><div class="prog"><i></i></div><span>0:34</span></div>
      ${sndBtn("mk" + (++mkCount), c.track, "Play with sound")}`,
    email: (c = SAMPLES.em1) => {
      const body = c.body === "dates"
        ? `<div class="edates"><span><b>12 Oct</b>London</span><span><b>19 Oct</b>Paris</span><span><b>02 Nov</b>Berlin</span><span><b>15 Nov</b>New York</span></div>`
        : c.body === "merch"
        ? `<div class="emerch"><span><i class="h1"></i>Hoodie<b>$65</b></span><span><i class="h2"></i>Tee<b>$35</b></span><span><i class="h3"></i>Cap<b>$28</b></span></div>`
        : `<div class="count"><span><b data-cd="d">02</b>days</span><span><b data-cd="h">14</b>hrs</span><span><b data-cd="m">36</b>min</span><span><b data-cd="s">09</b>sec</span></div>`;
      return `
      <div class="win"><div class="bar"><i></i><i></i><i></i><span class="url">Inbox · ${c.list}</span></div>
        <div class="cols">
          <ul class="inbox">
            <li><span class="ava"><img src="${OWNER}" alt=""></span><div><b>Jennie Dance Crew</b>${c.subject}</div><span class="new">NEW</span></li>
            <li><span class="ava">JD</span><div><b>Behind the dance</b>Watch the routine rehearsal</div></li>
            <li><span class="ava">♫</span><div><b>New lyric video</b>The words, on the beat</div></li>
            <li><span class="ava">★</span><div><b>Thank you</b>10K pre-saves — you did that</div></li>
          </ul>
          <div class="mail2">
            <div class="hero-img"><img src="${OWNER}" alt=""><b>${c.title}</b><small>${c.sub}</small></div>
            ${body}
            <span class="cta">${c.cta}</span>
          </div>
        </div>
      </div>
      <div class="chip c1">${c.s1[0]} <b>${c.s1[2] === "$" ? "$" : ""}<span data-num="${c.s1[1]}">0</span>${c.s1[2] === "$" ? "" : c.s1[2]}</b></div>
      <div class="chip c2">${c.s2[0]} <b>${c.s2[2] === "$" ? "$" : ""}<span data-num="${c.s2[1]}">0</span>${c.s2[2] === "$" ? "" : c.s2[2]}</b></div>`;
    },
    web: (c = SAMPLES.wb1, full) => {
      const sec = {
        player: `<section class="p-player"><span class="d"><img src="${OWNER}" alt=""></span><div class="meta2"><b>${c.title}</b>Now streaming<div class="pr"><i></i></div></div><span class="pb">▶</span></section>`,
        tour: `<section class="p-tour"><h5>Live dates</h5><div>12 Oct · London, O2 Academy<em>Tickets</em></div><div>19 Oct · Manchester, Albert Hall<em>Tickets</em></div><div>02 Nov · Paris, La Cigale<em>Tickets</em></div></section>`,
        tour2: `<section class="p-tour"><h5>North America</h5><div>15 Nov · New York, Irving Plaza<em>Sold out</em></div><div>20 Nov · Toronto, History<em>Tickets</em></div><div>28 Nov · LA, The Wiltern<em>Tickets</em></div></section>`,
        sign: `<section class="p-sign"><h5>Join the inner circle</h5><div class="inp"><span data-type>your@email.com</span><em>Join</em></div></section>`,
        watch: `<section class="p-tour"><h5>Watch</h5><div>Official dance video<em>Play</em></div><div>Lyric video<em>Play</em></div></section>`,
        about: `<section class="p-about"><h5>The story</h5><p>${c.title} is a cinematic release campaign built around movement, music and the fans who carry it. Every page, video and email tells the same story.</p><div class="p-stats"><span><b>2.4M</b>streams</span><span><b>120K</b>followers</span><span><b>18</b>countries</span></div></section>`,
        gallery: `<section class="p-gal"><h5>Gallery</h5><div class="ggrid"><span><img src="${OWNER}" alt=""></span><span>${vid(43209)}</span><span>${vid(39881)}</span><span><img src="${OWNER}" alt="" style="object-position:center 60%"></span></div></section>`,
        footer: `<footer class="p-foot"><b>${c.title}</b><div>Instagram · TikTok · YouTube · Spotify</div><small>Designed by Jennie Dance Crew</small></footer>`,
        releases: `<section class="p-rel"><h5>Releases</h5><div class="rgrid"><span class="r1"><b>Gold on My Skin</b></span><span class="r2"><b>Velvet</b></span><span class="r3"><b>Paper Hearts</b></span></div></section>`
      };
      return `
      <div class="win"><div class="bar"><i></i><i></i><i></i><span class="url">${c.url}</span></div>
        <div class="viewport">
          <div class="pg">
            <section class="p-hero">${vid(c.vid)}<h4>${c.title}</h4><p>${c.sub}</p><div class="pills2"><span class="presave">Pre-save</span><span>Spotify</span><span>Apple Music</span></div></section>
            ${(full ? [...c.sections, "about", "gallery", ...(c.sections.includes("tour") ? [] : ["tour"]), "footer"] : c.sections).map(k => sec[k]).join("")}
          </div>
          ${full ? `<div class="scroll-hint">Scroll to explore ↓</div>` : ""}
          <div class="toast">${c.sections.includes("tour") ? "Tickets reserved ✓" : "Pre-saved ✓"}</div>
          <div class="cursor"></div>
        </div>
      </div>
      <div class="chip c1">${c.s1[0]} <b><span data-num="${c.s1[1]}">0</span>${c.s1[2]}</b></div>
      <div class="chip c2">${c.s2[0]} <b><span data-num="${c.s2[1]}">0</span>${c.s2[2]}</b></div>`;
    }
  };
  function fillMocks(root = document) {
    $$("[data-mock]", root).forEach(m => { if (m.dataset.filled) return; const f = MOCK[m.dataset.mock]; if (!f) return; m.innerHTML = m.dataset.cfg ? f(SAMPLES[m.dataset.cfg], !!m.dataset.full) : f(); m.dataset.filled = 1; });
    $$(".svc-mock video", root).forEach(v => { v.muted = true; v.play().catch(() => {}); });
    $$("[data-num]", root).forEach(el => { if (window.__cio) window.__cio.observe(el); });
    $$(".scalebox", root).forEach(fitScale);
  }
  function fitScale(box) { const m = box.firstElementChild; if (m) m.style.transform = `scale(${box.clientWidth / 640})`; }
  const sro = new ResizeObserver(es => es.forEach(e => fitScale(e.target)));
  $$(".scalebox").forEach(b => sro.observe(b));
  window.__fillMocks = fillMocks;
  fillMocks();

  /* floating hearts on the phone */
  if (!reduce) setInterval(() => $$(".mk-dance .hearts").forEach(h => {
    if (!h.isConnected || h.getBoundingClientRect().bottom < 0) return;
    const i = document.createElement("i"); i.textContent = ["♥", "❤️", "💖", "🔥"][Math.floor(Math.random() * 4)];
    i.style.setProperty("--dx", (Math.random() * -50) + "px"); i.style.setProperty("--r", (Math.random() * 40 - 20) + "deg");
    h.appendChild(i); setTimeout(() => i.remove(), 2600);
  }), 650);
  let likes = 128400;
  setInterval(() => { likes += Math.floor(Math.random() * 90); $$("[data-likes]").forEach(el => el.textContent = (likes / 1000).toFixed(1) + "K"); }, 900);

  /* chips count up when visible */
  const fmt = (n, f) => f === "k" ? (n >= 1e6 ? (n / 1e6).toFixed(2) + "M" : Math.round(n / 1000) + "K") : n.toLocaleString();
  const cio = new IntersectionObserver(es => es.forEach(e => {
    if (!e.isIntersecting) return; cio.unobserve(e.target);
    const el = e.target, end = +el.dataset.num, t0 = performance.now();
    (function tick(t) { const p = Math.min((t - t0) / 1800, 1); el.textContent = fmt(Math.round(end * (1 - Math.pow(1 - p, 3))), el.dataset.fmt); if (p < 1) requestAnimationFrame(tick); })(t0);
  }), { threshold: .4 });
  $$("[data-num]").forEach(el => cio.observe(el)); window.__cio = cio;

  /* live countdown to next Friday */
  function nextFriday() { const d = new Date(); d.setDate(d.getDate() + ((5 - d.getDay() + 7) % 7 || 7)); d.setHours(0, 0, 0, 0); return d; }
  const release = nextFriday();
  setInterval(() => {
    let t = Math.max(0, release - Date.now()) / 1000;
    const v = { d: Math.floor(t / 86400), h: Math.floor(t % 86400 / 3600), m: Math.floor(t % 3600 / 60), s: Math.floor(t % 60) };
    $$("[data-cd]").forEach(el => el.textContent = String(v[el.dataset.cd]).padStart(2, "0"));
  }, 1000);

  /* typing email in landing page sign-up */
  const emails = ["amara@gmail.com", "leo.music@icloud.com", "fan4life@yahoo.com"]; let ei = 0;
  function typeLoop() {
    const target = emails[ei++ % emails.length]; let k = 0;
    const iv = setInterval(() => { $$("[data-type]").forEach(el => el.textContent = target.slice(0, k)); if (++k > target.length) { clearInterval(iv); setTimeout(typeLoop, 2200); } }, 90);
  }
  typeLoop();

  /* lyric videos: each one lands its words on the beat, synced to its own music when sound is on */
  const boxState = new WeakMap();
  setInterval(() => {
    $$(".ly-words").forEach(box => {
      const mock = box.closest(".svc-mock"); if (!mock || !mock.isConnected) return;
      let st = boxState.get(box);
      if (!st) { st = { lines: JSON.parse(box.dataset.lines), bpm: +box.dataset.bpm || 84, t: Math.random() * 4, idx: -1, line: -1 }; st.flat = st.lines.flatMap((l, li) => l.map((w, wi) => ({ li, wi }))); boxState.set(box, st); }
      const btn = $(".snd", mock), mine = btn && soundOwner === btn.dataset.snd && !music.paused;
      const t = mine ? music.currentTime : (st.t += 0.1);
      const idx = Math.floor(t / (60 / st.bpm));
      if (idx !== st.idx) {
        st.idx = idx; const it = st.flat[idx % st.flat.length];
        if (it.li !== st.line || !box.children.length) box.innerHTML = st.lines[it.li].map(w => `<span class="w${w[0] === "*" ? " hot" : ""}">${w.replace("*", "")}</span>`).join("");
        [...box.children].forEach((c, i) => c.classList.toggle("on", i <= it.wi)); st.line = it.li;
      }
      const dur = mine && music.duration ? music.duration : 34;
      const p = $(".ly-bar .prog i", mock); if (p) p.style.width = ((t % dur) / dur * 100) + "%";
      const tt = $(".ly-bar .t", mock); if (tt) tt.textContent = "0:" + String(Math.floor(t % dur)).padStart(2, "0");
    });
  }, 100);

  /* ================= MOTION ================= */
  /* curtain transition between pages */
  const curtain = $(".curtain");
  if (curtain && !reduce) {
    document.addEventListener("click", e => {
      const a = e.target.closest("a[href]"); if (!a) return;
      const href = a.getAttribute("href");
      if (a.target === "_blank" || e.metaKey || e.ctrlKey || e.shiftKey || !/\.html(\?|$)/.test(href)) return;
      e.preventDefault(); curtain.classList.add("in");
      setTimeout(() => location.href = href, 520);
    });
    window.addEventListener("pageshow", ev => { if (ev.persisted) curtain.classList.remove("in"); });
  }

  /* scroll progress + parallax */
  const bar = $("#progress"), para = $$(".portrait img");
  function onScrollFx() {
    const h = document.documentElement.scrollHeight - innerHeight;
    if (bar) bar.style.transform = `scaleX(${h > 0 ? scrollY / h : 0})`;
    if (!reduce) para.forEach(img => { if (!img.isConnected) return;
      const r = img.parentElement.getBoundingClientRect();
      const p = (r.top + r.height / 2 - innerHeight / 2) / innerHeight;
      img.style.transform = `scale(1.15) translateY(${p * -40}px)`;
    });
  }
  window.addEventListener("scroll", () => requestAnimationFrame(onScrollFx), { passive: true }); onScrollFx();

  /* split headings word by word */
  $$("main h1, main h2, .foot-top h3").forEach(h => {
    if (h.closest(".hero-name")) return;
    const words = h.textContent.trim().split(/\s+/);
    h.innerHTML = words.map((w, i) => `<span class="sw"><span style="--i:${i}">${w}</span></span>`).join(" ");
    h.classList.add("split");
  });
  const sio = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add("in"); sio.unobserve(e.target); } }), { threshold: .2 });
  $$(".split").forEach(h => sio.observe(h));

  /* footer letters */
  const fb = $(".foot-big");
  if (fb) { fb.innerHTML = [...fb.textContent.trim()].map((c, i) => `<span style="--i:${i}">${c}</span>`).join(""); sio.observe(fb); }

  /* automatic reveal variants on every card and block */
  const variants = [
    [".kicker", ""], [".stat", "zoom"], [".step", "zoom"], [".quote", "alt"], [".contact-card", "from-l"],
    [".faq details", "from-l"], [".field", ""], [".svc-vis", "clip"],
    [".svc-detail > div:last-child", "from-r"], [".vcard", "zoom"], [".work", "zoom"], [".foot-top > div", ""],
    [".filters button", ""], [".svc", "from-l"], [".socials a", "zoom"], [".place", ""]
  ];
  variants.forEach(([sel, v]) => $$(sel).forEach((el, i) => {
    if (el.closest(".hero")) return;
    el.classList.add("rv");
    if (v === "alt") el.classList.add(i % 2 ? "from-r" : "from-l");
    else if (v) el.classList.add(v);
    el.style.transitionDelay = ((i % 4) * 0.1) + "s";
    io.observe(el);
  }));

  setTimeout(() => $$(".portrait-wrap, .portrait").forEach(el => el.classList.add("in")), 1200);

  /* 3D tilt on cards */
  if (matchMedia("(pointer:fine)").matches && !reduce) {
    $$(".vcard, .work, .step, .quote, .stat, .contact-card, .svc-vis").forEach(el => {
      el.addEventListener("pointermove", e => {
        if (!el.classList.contains("in") && el.classList.contains("rv")) return;
        const r = el.getBoundingClientRect(), x = (e.clientX - r.left) / r.width - .5, y = (e.clientY - r.top) / r.height - .5;
        el.style.transition = "transform .15s ease-out";
        el.style.transform = `perspective(900px) rotateY(${x * 8}deg) rotateX(${y * -8}deg) translateY(-6px)`;
      });
      el.addEventListener("pointerleave", () => { el.style.transition = "transform .6s cubic-bezier(.2,.8,.2,1)"; el.style.transform = ""; });
    });
    /* magnetic buttons */
    $$(".btn, .links .book").forEach(b => {
      b.addEventListener("pointermove", e => { const r = b.getBoundingClientRect(); b.style.transform = `translate(${(e.clientX - r.left - r.width / 2) * .25}px, ${(e.clientY - r.top - r.height / 2) * .35}px)`; });
      b.addEventListener("pointerleave", () => b.style.transform = "");
    });
  }

  /* rising sparkles */
  if (!reduce) $$(".sparkles").forEach(box => {
    for (let i = 0; i < 18; i++) {
      const s = document.createElement("i");
      s.style.left = Math.random() * 100 + "%";
      s.style.animationDuration = (7 + Math.random() * 9) + "s";
      s.style.animationDelay = (-Math.random() * 12) + "s";
      box.appendChild(s);
    }
  });
})();
